public class Main {
    static int process(int[] arr) {
        int sum = 0;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] % 2 == 0) {
                sum += arr[i];
            } else {
                sum -= arr[i];
            }
        }
        return sum;
    }

    public static void main(String[] args) {
        int[] numbers = {1, 2, 3, 4, 5, 6};
        int result = process(numbers);
        System.out.println("result = " + result);

        int count = 0;
        for (int n : numbers) {
            if (n > 2) {
                count++;
            }
        }
        System.out.println("count = " + count);
    }
}

